39	    public Mono<ContentWrapper> getContent(String snapshotName, String baseSnapshotName) {
40	        if (StringUtils.isBlank(snapshotName) || StringUtils.isBlank(baseSnapshotName)) {
41	            return Mono.empty();
42	        }
43	        // TODO: refactor this method to use client.get instead of fetch but please be careful
44	        return client.fetch(Snapshot.class, baseSnapshotName)
45	                .doOnNext(this::checkBaseSnapshot)
46	                .flatMap(baseSnapshot -> {
47	                    if (StringUtils.equals(snapshotName, baseSnapshotName)) {
48	                        var contentWrapper = ContentWrapper.patchSnapshot(baseSnapshot, baseSnapshot);
49	                        return Mono.just(contentWrapper);
50	                    }
51	                    return client.fetch(Snapshot.class, snapshotName)
52	                            .map(snapshot -> ContentWrapper.patchSnapshot(snapshot, baseSnapshot));
53	                })
54	                .switchIfEmpty(Mono.defer(() -> {
55	                    log.error(
56	                            "The content snapshot [{}] or base snapshot [{}] not found.",
57	                            snapshotName,
58	                            baseSnapshotName);
59	                    return Mono.empty();
60	                }));
61	    }
