108	    private Mono<ListedPost> getListedPost(Post post) {
109	        Assert.notNull(post, "The post must not be null.");
110	        var listedPost = new ListedPost().setPost(post);
111	
112	        var statsMono = fetchStats(post).doOnNext(listedPost::setStats);
