119	        var contributorsMono = listContributors(post.getStatusOrDefault().getContributors())
120	                .collectList()
121	                .doOnNext(listedPost::setContributors);
122	
123	        var ownerMono = userService
124	                .getUserOrGhost(post.getSpec().getOwner())
125	                .map(user -> {
126	                    Contributor contributor = new Contributor();
127	                    contributor.setName(user.getMetadata().getName());
128	                    contributor.setDisplayName(user.getSpec().getDisplayName());
129	                    contributor.setAvatar(user.getSpec().getAvatar());
130	                    return contributor;
131	                })
132	                .doOnNext(listedPost::setOwner);
133	        return Mono.when(statsMono, tagsMono, categoriesMono, contributorsMono, ownerMono)
134	                .thenReturn(listedPost);
