174	    public Mono<Post> draftPost(PostRequest postRequest) {
175	        return Mono.defer(() -> {
176	                    var post = postRequest.post();
177	
178	                    if (post.getSpec().getOwner() != null) {
179	                        return Mono.just(post);
180	                    }
181	
182	                    return getContextUsername()
183	                            .doOnNext(username -> post.getSpec().setOwner(username))
184	                            .thenReturn(post);
185	                })
186	                .flatMap(client::create)
187	                .flatMap(post -> {
188	                    if (postRequest.content() == null) {
189	                        return Mono.just(post);
190	                    }
191	                    var contentRequest = new ContentRequest(
192	                            Ref.of(post),
193	                            post.getSpec().getHeadSnapshot(),
194	                            null,
195	                            postRequest.content().raw(),
196	                            postRequest.content().content(),
197	                            postRequest.content().rawType());
198	                    return draftContent(post.getSpec().getBaseSnapshot(), contentRequest)
199	                            .flatMap(contentWrapper -> waitForPostToDraftConcludingWork(
200	                                    post.getMetadata().getName(), contentWrapper));
201	                })
202	                .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
203	                        .filter(OptimisticLockingFailureException.class::isInstance));
204	    }
