206	    private Mono<Post> waitForPostToDraftConcludingWork(String postName, ContentWrapper contentWrapper) {
207	        return Mono.defer(() -> client.fetch(Post.class, postName).flatMap(post -> {
208	                    post.getSpec().setBaseSnapshot(contentWrapper.getSnapshotName());
209	                    post.getSpec().setHeadSnapshot(contentWrapper.getSnapshotName());
210	                    if (Objects.equals(true, post.getSpec().getPublish())) {
211	                        post.getSpec().setReleaseSnapshot(post.getSpec().getHeadSnapshot());
212	                    }
213	                    Condition condition = Condition.builder()
214	                            .type(Post.PostPhase.DRAFT.name())
215	                            .reason("DraftedSuccessfully")
216	                            .message("Drafted post successfully.")
217	                            .status(ConditionStatus.TRUE)
218	                            .lastTransitionTime(Instant.now())
219	                            .build();
220	                    Post.PostStatus status = post.getStatusOrDefault();
221	                    status.setPhase(Post.PostPhase.DRAFT.name());
222	                    status.getConditionsOrDefault().addAndEvictFIFO(condition);
223	                    return client.update(post);
224	                }))
225	                .retryWhen(Retry.backoff(5, Duration.ofMillis(100))
226	                        .filter(OptimisticLockingFailureException.class::isInstance));
227	    }
