133	    @Override
134	    public Mono<SinglePage> update(SinglePageRequest pageRequest) {
135	        SinglePage page = pageRequest.page();
136	        String headSnapshot = page.getSpec().getHeadSnapshot();
137	        String releaseSnapshot = page.getSpec().getReleaseSnapshot();
138	        String baseSnapshot = page.getSpec().getBaseSnapshot();
139	
140	        // create new snapshot to update first
141	        if (StringUtils.equals(headSnapshot, releaseSnapshot)) {
142	            return draftContent(baseSnapshot, pageRequest.contentRequest(), headSnapshot)
143	                    .flatMap(contentWrapper -> {
144	                        page.getSpec().setHeadSnapshot(contentWrapper.getSnapshotName());
145	                        return client.update(page);
146	                    });
147	        }
148	        return updateContent(baseSnapshot, pageRequest.contentRequest()).flatMap(contentWrapper -> {
149	            page.getSpec().setHeadSnapshot(contentWrapper.getSnapshotName());
150	            return client.update(page);
151	        });
152	    }
